import {test} from 'node:test';
import assert from 'node:assert/strict';
import {move} from '../src/status.mjs';

test('hidden check', async () => {
  const order = {status: 'received'};
  const paid = move(order, 'paid');
  const shipped = move(paid, 'shipped');
  assert.deepEqual(shipped.history, [{from: 'received', to: 'paid'}, {from: 'paid', to: 'shipped'}]);
  assert.deepEqual(paid.history, [{from: 'received', to: 'paid'}]);
  assert.equal(order.history, undefined);
  assert.equal(order.status, 'received');
});
